draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(0.1*W, 0.8*H, 0.8*W, 0.1*H);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0.1*W, 0.7*H);
  ctx.lineTo(0.1*W, 0.9*H);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0.9*W, 0.7*H);
  ctx.lineTo(0.9*W, 0.9*H);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Porch', 0.1*W, 0.7*H);
  ctx.beginPath();
  ctx.arc(0.5*W, 0.4*H, 0.2*W, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0.5*W + 0.1*W*Math.sin(t), 0.4*H, 0.05*W, 0, 2*Math.PI);
  ctx.stroke();
  ctx.restore();
}
